    /// Deletes all messages from a topic in a forum supergroup chat or a chat with a bot with topics; requires can_delete_messages administrator right in the supergroup
    /// unless the user is creator of the topic, the topic has no messages from other users and has at most 11 messages
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> DeleteForumTopicAsync(long chatId = default, int forumTopicId = default)
    {

           using var activity =  StartCallActivity("DeleteForumTopicAsync", typeof(DeleteForumTopic).FullName ?? "DeleteForumTopicAsync");

           try
           {
             return client.DeleteForumTopicAsync(chatId, forumTopicId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
